JS = "\nfunction openPcvOverlay(id){\n  document.querySelectorAll('.pcv-overlay').forEach(function(el){el.classList.remove('active');});\n  var el=document.getElementById(id);\n  if(el){el.classList.add('active');document.body.style.overflow='hidden';}\n}\nfunction closePcvOverlay(){\n  document.querySelectorAll('.pcv-overlay').forEach(function(el){el.classList.remove('active');});\n  document.body.style.overflow='';\n}\nfunction pcv2View(which){\n  var a=document.getElementById('pcv2A');\n  var b=document.getElementById('pcv2B');\n  if(!a||!b)return;\n  if(which==='B'){a.style.display='none';b.style.display='block';}\n  else{b.style.display='none';a.style.display='block';}\n}\n"

